/* From Uiverse.io by AlimurtuzaCodes - Tags: gradient, button, stars, css effect, css button, generate */
.__UIV_SCOPE__ .btn {
  border: none;
  width: 15em;
  height: 5em;
  border-radius: 3em;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  background: #1C1A1C;
  cursor: pointer;
  transition: all 450ms ease-in-out;
}

.__UIV_SCOPE__ .sparkle {
  fill: #AAAAAA;
  transition: all 800ms ease;
}

.__UIV_SCOPE__ .text {
  font-weight: 600;
  color: #AAAAAA;
  font-size: medium;
}

.__UIV_SCOPE__ .btn:hover {
  background: linear-gradient(0deg,#A47CF3,#683FEA);
  box-shadow: inset 0px 1px 0px 0px rgba(255, 255, 255, 0.4),
  inset 0px -4px 0px 0px rgba(0, 0, 0, 0.2),
  0px 0px 0px 4px rgba(255, 255, 255, 0.2),
  0px 0px 180px 0px #9917FF;
  transform: translateY(-2px);
}

.__UIV_SCOPE__ .btn:hover .text {
  color: white;
}

.__UIV_SCOPE__ .btn:hover .sparkle {
  fill: white;
  transform: scale(1.2);
}
